parameters.jsCode:
const input = $json;

// Scoring criteria
const weights = {
  required_skills: 30,
  experience: 25,
  projects: 15,
  education: 10,
  certifications: 5,
  languages: 5,
  additional_qualifications: 10
};

// Decision rules
function getDecision(score) {
  if (score >= 75) return "Interview";
  if (score >= 50) return "Maybe";
  return "Declined";
}

function getClassification(score) {
  if (score >= 75) return "Strong Match";
  if (score >= 50) return "Partial Match";
  return "Low Match";
}

const errors = [];
const warnings = [];

// 1. Extract LLM response
let evaluation =
  input.evaluation ??
  input.output ??
  input.text ??
  input.response ??
  input;

// 2. Parse JSON
if (typeof evaluation === "string") {
  try {
    evaluation = evaluation
      .replace(/```json\s*/gi, "")
      .replace(/```/g, "")
      .trim();

    evaluation = JSON.parse(evaluation);
  } catch (error) {
    return {
      json: {
        isValid: false,
        validationStatus: "FAILED",
        errors: ["Invalid JSON returned by LLM."],
        warnings: [],
        rawOutput: evaluation
      }
    };
  }
}

// 3. Validate object
if (
  !evaluation ||
  typeof evaluation !== "object" ||
  Array.isArray(evaluation)
) {
  return {
    json: {
      isValid: false,
      validationStatus: "FAILED",
      errors: ["Evaluation must be a JSON object."]
    }
  };
}

// 4. Required fields
const requiredFields = [
  "candidate_name",
  "applied_position",
  "score",
  "classification",
  "recommendation",
  "criteria_scores",
  "decision_reason",
  "matched_requirements",
  "partially_matched_requirements",
  "missing_requirements",
  "strengths",
  "weaknesses",
  "experience_summary",
  "interview_questions",
  "evaluation_confidence"
];

for (const field of requiredFields) {
  if (
    evaluation[field] === undefined ||
    evaluation[field] === null
  ) {
    errors.push(`Missing required field: ${field}`);
  }
}

// 5. Validate candidate information
if (
  typeof evaluation.candidate_name !== "string" ||
  !evaluation.candidate_name.trim()
) {
  errors.push("Invalid candidate name.");
}

if (
  typeof evaluation.applied_position !== "string" ||
  !evaluation.applied_position.trim()
) {
  errors.push("Invalid applied position.");
}

// 6. Validate criteria and calculate score
let calculatedScore = 0;
let criteriaValid = true;

if (
  !evaluation.criteria_scores ||
  typeof evaluation.criteria_scores !== "object"
) {
  errors.push("Invalid criteria_scores.");
  criteriaValid = false;
} else {
  for (const [criterion, maxScore] of Object.entries(weights)) {
    const item = evaluation.criteria_scores[criterion];

    if (!item || typeof item !== "object") {
      errors.push(`Missing criterion: ${criterion}`);
      criteriaValid = false;
      continue;
    }

    if (
      typeof item.score !== "number" ||
      !Number.isFinite(item.score) ||
      item.score < 0 ||
      item.score > maxScore
    ) {
      errors.push(
        `Invalid score for ${criterion}. Allowed: 0-${maxScore}.`
      );
      criteriaValid = false;
      continue;
    }

    if (item.max_score !== maxScore) {
      warnings.push(
        `${criterion}: max_score corrected to ${maxScore}.`
      );
      item.max_score = maxScore;
    }

    if (
      typeof item.reason !== "string" ||
      !item.reason.trim()
    ) {
      warnings.push(`Missing reason for ${criterion}.`);
    }

    calculatedScore += item.score;
  }
}

// 7. Recalculate total score
if (criteriaValid) {
  calculatedScore = Math.round(calculatedScore * 100) / 100;

  if (evaluation.score !== calculatedScore) {
    warnings.push(
      `Score corrected from ${evaluation.score} to ${calculatedScore}.`
    );
  }

  evaluation.score = calculatedScore;
} else {
  evaluation.score = null;
}

// 8. Correct classification and recommendation
if (criteriaValid) {
  const expectedDecision = getDecision(calculatedScore);
  const expectedClassification = getClassification(calculatedScore);

  if (evaluation.recommendation !== expectedDecision) {
    warnings.push(
      `Recommendation corrected from "${evaluation.recommendation}" to "${expectedDecision}".`
    );
  }

  if (evaluation.classification !== expectedClassification) {
    warnings.push(
      `Classification corrected from "${evaluation.classification}" to "${expectedClassification}".`
    );
  }

  evaluation.recommendation = expectedDecision;
  evaluation.classification = expectedClassification;
}

// 9. Validate arrays
const arrayFields = [
  "matched_requirements",
  "partially_matched_requirements",
  "missing_requirements",
  "strengths",
  "weaknesses",
  "interview_questions"
];

for (const field of arrayFields) {
  if (!Array.isArray(evaluation[field])) {
    errors.push(`${field} must be an array.`);
  }
}

// 10. Validate confidence
if (
  !["High", "Medium", "Low"].includes(
    evaluation.evaluation_confidence
  )
) {
  errors.push("Invalid evaluation_confidence.");
}

// 11. Validate decision reason
if (
  typeof evaluation.decision_reason !== "string" ||
  !evaluation.decision_reason.trim()
) {
  errors.push("Missing decision_reason.");
}

// 12. Final result
const isValid = errors.length === 0 && criteriaValid;

return {
  json: {
    isValid,
    validationStatus: isValid ? "PASSED" : "FAILED",
    hiringDecision: isValid ? evaluation.recommendation : null,
    calculatedScore: criteriaValid ? calculatedScore : null,
    errors,
    warnings,
    evaluation
  }
};
